from functools import lru_cache


@lru_cache(maxsize=None)
def get_max_sum(n):
    """Write a function to find the maximum sum possible by using the given equation f(n) = max( (f(n/2) + f(n/3) + f(n/4) + f(n/5)), n)."""
    if n <= 0:
        return n
    split_sum = (
        get_max_sum(n // 2)
        + get_max_sum(n // 3)
        + get_max_sum(n // 4)
        + get_max_sum(n // 5)
    )
    return max(n, split_sum)
